from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from .models import CustomerInvoice
from .serializers import InvoiceSummarySerializer

class InvoiceAccountExportView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def get(self, request):
        account_code = request.query_params.get('account_code')
        if not account_code:
            return Response({'error': 'account_code required'}, status=status.HTTP_400_BAD_REQUEST)

        invoices = CustomerInvoice.objects.filter(
            organization=request.user.organization,
            billing_account_ref=account_code,
            status='ISSUED'
        )
        serializer = InvoiceSummarySerializer(invoices, many=True)
        return Response(serializer.data)
